def first_or(xs: list[int], default: int) -> int:
    """Return the first element, or `default` for an empty list."""
    return xs[0] if xs else default


def test_first_or_empty() -> None:
    assert first_or([], 0) == 0
    assert first_or([], -1) == -1


def test_first_or_non_empty() -> None:
    assert first_or([42], 0) == 42
    assert first_or([1, 2, 3], 99) == 1
    assert first_or([-5, 10], 0) == -5

